/**
 * How much do we actually know about this tool?
 *
 * Audit fix 1.1 — the site previously rendered an identical "Evidence Card"
 * reading "Hands-on + Vendor Data / Test Date 2026-08-01" on all 200 tool
 * pages, while 153 of them were machine-generated by scripts/gen-tools.mjs
 * with reviewsCount: 0. That is a Google scaled-content-abuse pattern and an
 * FTC 16 CFR 255 deceptive-claim risk next to an affiliate link.
 *
 * Every claim the UI makes is now gated on this field:
 *  - 'hands-on-tested'   we ran the tool ourselves. Requires testedAt and
 *                        should carry evidenceUrls. Only these may show an
 *                        Evidence Card and a numeric editorial score.
 *  - 'pricing-verified'  we did not run it, but a human opened the vendor
 *                        pricing page. Requires pricingSourceUrl +
 *                        pricingCheckedAt.
 *  - 'listed-only'       catalogued from public information. No test claim,
 *                        no score. This is the honest default.
 */
export type VerificationLevel = 'hands-on-tested' | 'pricing-verified' | 'listed-only';

/**
 * Multi-dimensional editorial scoring (audit fix 2.1).
 * A single 4.1–4.9 number carried no information — no tool scored below 4.0
 * and the average was 4.46. Sub-scores are 0–10 and only ever exist on tools
 * we genuinely tested. `overall` is computed, never hand-written.
 */
export interface ToolScores {
  outputQuality: number;
  speed: number;
  valueForMoney: number;
  easeOfUse: number;
  /** Watermark-free? Commercial rights? Usable resolution? */
  exportFreedom: number;
}

export interface ToolVerdict {
  bestFor: string;
  skipIf: string;
}

/** A parsed public plan from the vendor's official pricing page. */
export interface PricingPlan {
  name: string;
  priceDisplay: string;
  billing: string;
  features?: string[];
}

export interface Tool {
  id: string;
  name: string;
  slug: string;
  tagline: string;
  description: string;
  url: string;
  affiliateUrl?: string;
  /**
   * Which affiliate network the link above belongs to.
   * Audit fix 1.6 — 15 tools carried invented ?via=creatoraihub /
   * ?ref=creatoraihub parameters for programs that were never joined, so every
   * rel="sponsored" click earned nothing while the footer claimed an affiliate
   * relationship. affiliateUrl is now ignored at redirect time unless this is
   * set to a real, approved program.
   */
  affiliateProgram?: 'impact' | 'partnerstack' | 'rewardful' | 'direct' | null;
  logo: string;
  /** Local brand cover is generated by CoverArt; remote stock imagery was removed (v2.6). */
  coverImage?: string;
  category: ToolCategory;
  pricing: 'Free' | 'Freemium' | 'Paid' | 'Free Trial';
  startingPrice?: string;
  rating: number;
  reviewsCount: number;
  ratingLabel?: 'Editorial Score' | 'Community Score';
  isFeatured: boolean;
  isEditorsChoice: boolean;
  isTrending: boolean;
  isNew: boolean;
  hasFounderBadge: boolean;
  tags: string[];
  metrics?: string;
  launchDate?: string;
  cataloguedAt?: string;

  /* ---- Evidence & verification (audit fixes 1.1, 1.2, 2.1, 2.3) ---- */

  verificationLevel: VerificationLevel;
  /** ISO date of a real hands-on test. Only set for 'hands-on-tested'. */
  testedAt?: string;
  /** Screenshots, output videos, changelogs backing the review. */
  evidenceUrls?: string[];
  /** Which paid plan the test was run on, e.g. "Pro $29/mo". */
  planTested?: string;

  /* ---- Enriched editorial description (2026-08-06) ---- */
  /** Longer, platform-ready description for the tool page body. */
  longDescription?: string;
  /** One-line intro used at the top of the tool page. */
  pageIntro?: string;
  /** Short "best for" statement. */
  bestFor?: string;
  /** Capability list (richer than tags). */
  keyCapabilities?: string[];
  /** ISO date this editorial description was written. */
  descriptionUpdatedAt?: string;
  /** Who wrote it / basis (never a fabricated vendor claim). */
  descriptionSource?: string;
  /** Vendor pricing page the startingPrice was read from. */
  pricingSourceUrl?: string;
  /** ISO date the pricing was last confirmed against the vendor page. */
  pricingCheckedAt?: string;

  /* ---- Price-check evidence (2026-08-06 source crawl) ---- */

  /** How far the price check went: complete | partial | source-captured | manual. */
  priceCheckStatus?: 'complete' | 'partial' | 'source-captured' | 'source-unavailable' | 'manual';
  /** Human note on currency, billing quirks, annual-equivalent, rebrands, etc. */
  priceCheckNote?: string;
  /** Parsed public plans from the official pricing page (name, price, billing, features). */
  pricingPlans?: PricingPlan[];

  scores?: ToolScores;
  verdict?: ToolVerdict;
  /** Audit fix 2.1 — no tool on the site had a single listed drawback. */
  pros?: string[];
  cons?: string[];
}

/**
 * Shape of the raw catalog entries in tools.ts / tools-extended.ts.
 *
 * Seed data deliberately CANNOT declare its own verification level, test date
 * or scores — those are granted centrally in verified-tools.ts. This makes the
 * "we tested this" claim impossible to fake by editing a generated file.
 */
export type ToolSeed = Omit<
  Tool,
  'verificationLevel' | 'testedAt' | 'evidenceUrls' | 'planTested' | 'scores' | 'verdict' | 'pros' | 'cons'
>;

/** The evidence a hand-verified tool must supply. */
export type VerifiedRecord = Partial<Tool> & { verificationLevel: VerificationLevel };

/** Weighted overall score, 0–10, derived from sub-scores. Never hand-authored. */
export function computeOverall(s: ToolScores): number {
  const weighted =
    s.outputQuality * 0.35 +
    s.easeOfUse * 0.2 +
    s.valueForMoney * 0.2 +
    s.speed * 0.15 +
    s.exportFreedom * 0.1;
  return Math.round(weighted * 10) / 10;
}

/** True only when a numeric score is defensible to a regulator. */
export function hasVerifiedScore(t: Tool): boolean {
  return t.verificationLevel === 'hands-on-tested' && !!t.scores && !!t.testedAt;
}

export type ToolCategory =
  | 'Video Generation'
  | 'Video Editing & VFX'
  | 'Video Repurposing'
  | 'Faceless Video'
  | 'Voice & Audio'
  | 'Translation & Dubbing'
  | 'Music & SFX'
  | 'AI Avatars'
  | 'Thumbnails & Design'
  | 'Scripting & Writing'
  | 'AI Agents & Assistants'
  | 'Prompts & Templates'
  | 'Transcription & Captions'
  | 'SEO & Analytics'
  | 'Automation'
  | 'Live & Streaming'
  | '3D & Motion';

/**
 * Critique §5 fix — four missing categories added:
 * Translation & Dubbing (the biggest lever for international channel growth),
 * Faceless Video (a large sub-niche that was scattered across other groups),
 * AI Agents & Assistants (general assistants previously filed under writing)
 * and Prompts & Templates. Every category carries hand-written editorial copy
 * in src/lib/categories.ts.
 */
