// ---- Merge in the extended curated dataset (150+ tools) ----
import { EXTENDED_TOOLS } from './tools-extended';
import { DEAD_TOOL_SLUGS } from './graveyard';
import { VERIFIED_TOOLS } from './verified-tools';
import { TOOL_DESCRIPTIONS } from './descriptions';

/**
 * Audit fix 1.1 / 1.2.
 *
 * Nothing in the raw seed arrays carries a verification claim. This is the
 * single place where verification is applied, and it only ever grants a level
 * above 'listed-only' when there is a matching hand-authored record in
 * verified-tools.ts. It is deliberately impossible to earn an Evidence Card by
 * editing a machine-generated file.
 */
function applyVerification(t: ToolSeed): Tool {
  const verified = VERIFIED_TOOLS[t.slug];
  // Editorial descriptions are granted centrally too (never trusted from the
  // machine-generated seed file), exactly like verification level.
  const desc = TOOL_DESCRIPTIONS[t.slug];

  const base = {
    ...t,
    ...desc,
  };

  if (!verified) {
    // Honest default: catalogued, not tested. No numeric score is surfaced,
    // and reviewsCount is trusted only when it came from a real source.
    return {
      ...base,
      verificationLevel: 'listed-only',
      cataloguedAt: t.cataloguedAt ?? undefined,
      testedAt: undefined,
      scores: undefined,
    };
  }

  return {
    ...base,
    ...verified,
    verificationLevel: verified.verificationLevel,
  };
}

/** The complete, deduplicated tool catalog used across the whole site. */
export const ALL_TOOLS: Tool[] = (() => {
  const seen = new Set<string>();
  const merged: Tool[] = [];
  for (const seed of [...INITIAL_TOOLS, ...EXTENDED_TOOLS]) {
    // Audit fix 1.5 — Play.ht, Hour One and Morningfame are confirmed dead
    // (DNS does not resolve / server never answers). They now live in the
    // graveyard with a migration path instead of sending users to a timeout.
    if (DEAD_TOOL_SLUGS.has(seed.slug)) continue;
    if (seen.has(seed.slug)) continue;
    seen.add(seed.slug);
    merged.push(applyVerification(seed));
  }
  return merged;
})();

/** Tools we genuinely ran ourselves — the only ones allowed an Evidence Card. */
export const TESTED_TOOLS: Tool[] = ALL_TOOLS.filter(hasVerifiedScore);

export const UNIQUE_TOOLS = ALL_TOOLS;
export const getFeaturedTools = () => ALL_TOOLS.filter((t) => t.isFeatured);
export const getToolsByCategory = (category: Category) =>
  category === 'All' ? ALL_TOOLS : ALL_TOOLS.filter((t) => t.category === category);
export const searchTools = (query: string) => {
  const q = query.toLowerCase();
  return ALL_TOOLS.filter(
    (t) =>
      t.name.toLowerCase().includes(q) ||
      t.tagline.toLowerCase().includes(q) ||
      t.description.toLowerCase().includes(q) ||
      t.tags.some((tag) => tag.toLowerCase().includes(q))
  );
};
export const filterByPricing = (tools: Tool[], pricing: PricingOption) =>
  pricing === 'All' ? tools : tools.filter((t) => t.pricing === pricing);
